import { SimulationClock } from './SimulationClock'

// Coordinates one run. Gameplay counters, movement and wildlife share the same steps.
export class RunSession {
  constructor(){this.clock=new SimulationClock();this.run=null;this.paused=true}
  pause(){this.clock.reset();this.paused=true}
  advance(game,now){
    const {state,world,player}=game,run=state.currentRun
    if(!game.active){state.pauseHunt();this.pause();return 0}
    if(run!==this.run||this.paused){this.clock.reset();this.run=run;this.paused=false}
    const [side,forward]=game.controls.axes()
    if(side||forward)game.dismissHint()
    player.sprinting=!player.crouched&&game.controls.wantsSprint()
    return this.clock.advance(now,(seconds,milliseconds)=>{
      if(!game.active)return false
      world.move(player,side,forward,seconds)
      if(state.visitPosition(player.x,player.z)){
        game.feedback=state.commission.completed?'观察委托完成！手记已收藏':'已到达路标，手记已记录'
        game.feedbackUntil=Date.now()+3000;game.uiDirty=true;game.save()
      }
      if(run.lastHuntTickAt===null)state.tickHunt(0)
      const result=state.tickHunt(run.lastHuntTickAt+milliseconds)||world.wildlife.update(state,seconds,player)
      if(result){game.save();game._showResult(result);this.pause();return false}
    })
  }
}
